public class ReadScores {
    public static void main(String[] args) throws IOException {
        try (Scanner scanner = new Scanner(Path.of("scores.txt"), StandardCharsets.UTF_8)) {
            double sum = 0;
            int count = 0;
            while (scanner.hasNextDouble()) {
